import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;
import javax.annotation.Nullable;
import net.minecraft.world.item.Tier;
import net.minecraftforge.common.TierSortingRegistry;
import se.mickelus.tetra.data.DataManager;

public class TierHelper {
    public static List<Tier> tiers = Collections.emptyList();

    public static void init() {
        DataManager.instance.tierData.onReload(TierHelper::setupTiers);
    }

    private static void setupTiers() {
        List relevant = DataManager.instance.tierData.getData().values().stream().flatMap(Arrays::stream).distinct().collect(Collectors.toList());
        tiers = TierSortingRegistry.getSortedTiers().stream().filter(tier -> relevant.contains(TierSortingRegistry.getName((Tier)tier))).collect(Collectors.toList());
    }

    public static int getIndex(Tier tier) {
        return tiers.indexOf(tier);
    }

    @Nullable
    public static Tier getTier(int index) {
        if (index > -1) {
            return tiers.get(Math.min(index, tiers.size() - 1));
        }
        return null;
    }
}

